/// <summary>
/// MPJ_33690_PurchaseOrderChangeService Purchase Order service Contract
/// </summary>
[DataContractAttribute]
class METPurchaseOrderServiceLinesContract
{
    TradeLineNumber                 lineNumber;
    PdsCWInventQty                  cwQuantity;
    InventQty                       purchaseQty;



}

Method.Source:
    [DataMemberAttribute('lineNumber')]
    public TradeLineNumber parmLineNumber(TradeLineNumber  _lineNumber = lineNumber)
    {
        lineNumber = _lineNumber;

        return lineNumber;
    }

    [DataMemberAttribute('cwQuantity')]
    public PdsCWInventQty parmCWQuantity(PdsCWInventQty  _cwQuantity = cwQuantity)
    {
        cwQuantity = _cwQuantity;

        return cwQuantity;
    }

    [DataMemberAttribute('purchaseQty')]
    public InventQty parmPurchaseQty(InventQty  _purchaseQty = purchaseQty)
    {
        purchaseQty = _purchaseQty;

        return purchaseQty;
    }
